KIND = "atlas"
SYSTEM = "muscular"
E = {
"m-pterygoideus-medialis": {
"en": ["Medial pterygoid", "A quadrilateral muscle of mastication on the inner surface of the ramus of the mandible, mirroring masseter; together they form a muscular sling around the angle of the mandible.",
 ["Deep head: inner surface of the lateral pterygoid plate (pterygoid fossa) and pyramidal process of the palatine bone; superficial head: maxillary tuberosity",
  "Inner surface of the angle of the mandible (pterygoid tuberosity)", "Nerve to medial pterygoid (mandibular nerve, V3)", "Pterygoid branches of the maxillary artery",
  "Elevates the mandible (closes the mouth) and assists protrusion; acting on one side it moves the jaw to the opposite side"], [], [],
 ["With masseter it forms the 'pterygomasseteric sling', which determines displacement of fragments in fractures of the mandibular angle.", "Its nerve also supplies tensor tympani and tensor veli palatini."], ["pterygoid"]],
"fr": ["Muscle ptérygoïdien médial", "Muscle masticateur quadrilatère situé à la face interne de la branche mandibulaire, en miroir du masséter ; ensemble ils forment une sangle autour de l'angle de la mandibule.",
 ["Chef profond : face interne de la lame latérale du processus ptérygoïde (fosse ptérygoïdienne) et processus pyramidal de l'os palatin ; chef superficiel : tubérosité maxillaire",
  "Face interne de l'angle mandibulaire (tubérosité ptérygoïdienne)", "Nerf du ptérygoïdien médial (nerf mandibulaire, V3)", "Rameaux ptérygoïdiens de l'artère maxillaire",
  "Élève la mandibule (ferme la bouche) et participe à la propulsion ; en contraction unilatérale, déplace la mâchoire du côté opposé"], [], [],
 ["Avec le masséter il forme la « sangle ptérygo-massétérine », qui conditionne le déplacement des fragments dans les fractures de l'angle mandibulaire.", "Son nerf innerve aussi le tenseur du tympan et le tenseur du voile du palais."], ["ptérygoïdien interne"]],
"de": ["M. pterygoideus medialis", "Viereckiger Kaumuskel an der Innenfläche des Ramus mandibulae, das Gegenstück zum Masseter; zusammen bilden sie eine Muskelschlinge um den Kieferwinkel.",
 ["Tiefer Kopf: Innenfläche der Lamina lateralis processus pterygoidei (Fossa pterygoidea) und Processus pyramidalis ossis palatini; oberflächlicher Kopf: Tuber maxillae",
  "Innenfläche des Angulus mandibulae (Tuberositas pterygoidea)", "N. pterygoideus medialis (N. mandibularis, V3)", "Rr. pterygoidei der A. maxillaris",
  "Hebt den Unterkiefer (Mundschluss) und unterstützt die Protrusion; einseitig verschiebt er den Kiefer zur Gegenseite"], [], [],
 ["Mit dem Masseter bildet er die „pterygomasseterische Schlinge“, die bei Kieferwinkelfrakturen die Fragmentverschiebung bestimmt.", "Sein Nerv versorgt auch den M. tensor tympani und den M. tensor veli palatini."], ["innerer Flügelmuskel"]],
"es": ["Músculo pterigoideo medial", "Músculo masticador cuadrilátero en la cara interna de la rama mandibular, homólogo del masetero; juntos forman una cincha muscular alrededor del ángulo de la mandíbula.",
 ["Cabeza profunda: cara interna de la lámina lateral de la apófisis pterigoides (fosa pterigoidea) y apófisis piramidal del palatino; cabeza superficial: tuberosidad del maxilar",
  "Cara interna del ángulo mandibular (tuberosidad pterigoidea)", "Nervio del pterigoideo medial (nervio mandibular, V3)", "Ramas pterigoideas de la arteria maxilar",
  "Eleva la mandíbula (cierra la boca) y participa en la protrusión; en contracción unilateral desplaza la mandíbula al lado opuesto"], [], [],
 ["Con el masetero forma la «cincha pterigomaseterina», que determina el desplazamiento de los fragmentos en las fracturas del ángulo mandibular.", "Su nervio inerva también el tensor del tímpano y el tensor del velo del paladar."], ["pterigoideo interno"]],
},
"m-rectus-superior": {
"en": ["Superior rectus", "The straight muscle attached to the upper surface of the eyeball that raises the eye.",
 ["Common tendinous ring (upper part)", "Sclera, about 7.5 mm above and behind the cornea", "Oculomotor nerve (III), superior division", "Muscular branches of the ophthalmic artery",
  "Elevation (most effective with the eye abducted), adduction and intorsion"], [], [],
 ["To test pure elevation, the eye is first turned outwards (abduction) and then asked to look up."], []],
"fr": ["Muscle droit supérieur", "Muscle droit fixé à la face supérieure du globe oculaire, qui élève l'œil.",
 ["Anneau tendineux commun (partie supérieure)", "Sclère, environ 7,5 mm au-dessus et en arrière de la cornée", "Nerf oculomoteur (III), branche supérieure", "Rameaux musculaires de l'artère ophtalmique",
  "Élévation (plus efficace œil en abduction), adduction et intorsion"], [], [],
 ["Pour tester l'élévation pure, on fait d'abord tourner l'œil en dehors (abduction) puis regarder en haut."], []],
"de": ["M. rectus superior", "Gerader Augenmuskel an der Oberseite des Augapfels, der das Auge hebt.",
 ["Anulus tendineus communis (oberer Teil)", "Sklera, etwa 7,5 mm oberhalb und hinter der Hornhaut", "N. oculomotorius (III), oberer Ast", "Muskeläste der A. ophthalmica",
  "Hebung (am wirksamsten bei abduziertem Auge), Adduktion und Innenrollung"], [], [],
 ["Zur Prüfung der reinen Hebung wird das Auge zuerst nach außen (Abduktion) gewendet und dann nach oben geblickt."], ["oberer gerader Augenmuskel"]],
"es": ["Músculo recto superior", "Músculo recto fijado a la cara superior del globo ocular que eleva el ojo.",
 ["Anillo tendinoso común (parte superior)", "Esclera, unos 7,5 mm por encima y detrás de la córnea", "Nervio oculomotor (III), rama superior", "Ramas musculares de la arteria oftálmica",
  "Elevación (más eficaz con el ojo en abducción), aducción e intorsión"], [], [],
 ["Para explorar la elevación pura, se lleva primero el ojo hacia fuera (abducción) y luego se pide mirar arriba."], []],
},
"m-rectus-inferior": {
"en": ["Inferior rectus", "The straight muscle attached to the lower surface of the eyeball that lowers the eye.",
 ["Common tendinous ring (lower part)", "Sclera, about 6.5 mm below and behind the cornea", "Oculomotor nerve (III), inferior division", "Muscular branches of the ophthalmic artery, infraorbital artery",
  "Depression (most effective in abduction), adduction and extorsion"], [],
 ["In an orbital floor (blow-out) fracture the muscle can be trapped towards the maxillary sinus, causing double vision and restriction on looking up."], [], []],
"fr": ["Muscle droit inférieur", "Muscle droit fixé à la face inférieure du globe oculaire, qui abaisse l'œil.",
 ["Anneau tendineux commun (partie inférieure)", "Sclère, environ 6,5 mm au-dessous et en arrière de la cornée", "Nerf oculomoteur (III), branche inférieure", "Rameaux musculaires de l'artère ophtalmique, artère infra-orbitaire",
  "Abaissement (plus efficace en abduction), adduction et extorsion"], [],
 ["Dans une fracture du plancher de l'orbite (blow-out), le muscle peut s'incarcérer vers le sinus maxillaire, avec diplopie et limitation du regard vers le haut."], [], []],
"de": ["M. rectus inferior", "Gerader Augenmuskel an der Unterseite des Augapfels, der das Auge senkt.",
 ["Anulus tendineus communis (unterer Teil)", "Sklera, etwa 6,5 mm unterhalb und hinter der Hornhaut", "N. oculomotorius (III), unterer Ast", "Muskeläste der A. ophthalmica, A. infraorbitalis",
  "Senkung (am wirksamsten in Abduktion), Adduktion und Außenrollung"], [],
 ["Bei einer Orbitabodenfraktur (Blow-out) kann der Muskel zur Kieferhöhle hin eingeklemmt werden; es entstehen Doppelbilder und eine Hebungseinschränkung."], [], ["unterer gerader Augenmuskel"]],
"es": ["Músculo recto inferior", "Músculo recto fijado a la cara inferior del globo ocular que desciende el ojo.",
 ["Anillo tendinoso común (parte inferior)", "Esclera, unos 6,5 mm por debajo y detrás de la córnea", "Nervio oculomotor (III), rama inferior", "Ramas musculares de la arteria oftálmica, arteria infraorbitaria",
  "Depresión (más eficaz en abducción), aducción y extorsión"], [],
 ["En la fractura del suelo de la órbita (blow-out) el músculo puede quedar atrapado hacia el seno maxilar, con diplopía y limitación de la mirada hacia arriba."], [], []],
},
"m-rectus-medialis": {
"en": ["Medial rectus", "The strongest extra-ocular muscle, attached to the medial surface of the eyeball; it turns the eye towards the nose.",
 ["Common tendinous ring (medial part)", "Sclera, about 5.5 mm medial to and behind the cornea", "Oculomotor nerve (III), inferior division", "Muscular branches of the ophthalmic artery",
  "Adduction"], [],
 ["In oculomotor nerve palsy the eye looks 'down and out' (lateral rectus and superior oblique are unopposed), with ptosis and mydriasis.", "In internuclear ophthalmoplegia (MLF lesion) adduction of the eye on the same side fails on lateral gaze."], [], []],
"fr": ["Muscle droit médial", "Le plus puissant des muscles oculomoteurs, fixé à la face médiale du globe oculaire ; il tourne l'œil vers le nez.",
 ["Anneau tendineux commun (partie médiale)", "Sclère, environ 5,5 mm en dedans et en arrière de la cornée", "Nerf oculomoteur (III), branche inférieure", "Rameaux musculaires de l'artère ophtalmique",
  "Adduction"], [],
 ["Dans la paralysie du nerf oculomoteur, l'œil regarde « en bas et en dehors » (droit latéral et oblique supérieur sans antagonistes), avec ptosis et mydriase.", "Dans l'ophtalmoplégie internucléaire (lésion du FLM), l'adduction de l'œil homolatéral est déficiente dans le regard latéral."], [], []],
"de": ["M. rectus medialis", "Der kräftigste äußere Augenmuskel an der Innenseite des Augapfels; er dreht das Auge zur Nase.",
 ["Anulus tendineus communis (medialer Teil)", "Sklera, etwa 5,5 mm medial und hinter der Hornhaut", "N. oculomotorius (III), unterer Ast", "Muskeläste der A. ophthalmica",
  "Adduktion"], [],
 ["Bei Okulomotoriusparese blickt das Auge „nach unten außen“ (Rectus lateralis und Obliquus superior ohne Gegenspieler), begleitet von Ptosis und Mydriasis.", "Bei internukleärer Ophthalmoplegie (MLF-Läsion) ist beim Seitblick die Adduktion des gleichseitigen Auges gestört."], [], ["innerer gerader Augenmuskel"]],
"es": ["Músculo recto medial", "El músculo extraocular más fuerte, fijado a la cara medial del globo ocular; gira el ojo hacia la nariz.",
 ["Anillo tendinoso común (parte medial)", "Esclera, unos 5,5 mm medial y detrás de la córnea", "Nervio oculomotor (III), rama inferior", "Ramas musculares de la arteria oftálmica",
  "Aducción"], [],
 ["En la parálisis del oculomotor el ojo mira «abajo y afuera» (recto lateral y oblicuo superior sin oposición), con ptosis y midriasis.", "En la oftalmoplejía internuclear (lesión del FLM) falla la aducción del ojo del mismo lado en la mirada lateral."], [], []],
},
"m-rectus-lateralis": {
"en": ["Lateral rectus", "The muscle attached to the lateral surface of the eyeball that turns the eye outwards; the only muscle supplied by the abducens nerve.",
 ["Common tendinous ring (lateral part, two heads)", "Sclera, about 7 mm lateral to and behind the cornea", "Abducens nerve (VI)", "Muscular branches of the ophthalmic artery, lacrimal artery",
  "Abduction"], [],
 ["In abducens palsy the eye turns in (esotropia) with horizontal double vision; because of its long intracranial course it is among the first cranial nerves affected by raised intracranial pressure."],
 ["Mnemonic: LR6 SO4, the rest 3 (lateral rectus VI, superior oblique IV, the others III)."], []],
"fr": ["Muscle droit latéral", "Muscle fixé à la face latérale du globe oculaire qui tourne l'œil en dehors ; seul muscle innervé par le nerf abducens.",
 ["Anneau tendineux commun (partie latérale, deux chefs)", "Sclère, environ 7 mm en dehors et en arrière de la cornée", "Nerf abducens (VI)", "Rameaux musculaires de l'artère ophtalmique, artère lacrymale",
  "Abduction"], [],
 ["Dans la paralysie de l'abducens, l'œil dévie en dedans (ésotropie) avec diplopie horizontale ; en raison de son long trajet intracrânien, c'est l'un des premiers nerfs crâniens touchés par l'hypertension intracrânienne."],
 ["Moyen mnémotechnique : DL6 OS4, les autres 3 (droit latéral VI, oblique supérieur IV, les autres III)."], []],
"de": ["M. rectus lateralis", "Muskel an der Außenseite des Augapfels, der das Auge nach außen dreht; der einzige vom N. abducens innervierte Muskel.",
 ["Anulus tendineus communis (lateraler Teil, zweiköpfig)", "Sklera, etwa 7 mm lateral und hinter der Hornhaut", "N. abducens (VI)", "Muskeläste der A. ophthalmica, A. lacrimalis",
  "Abduktion"], [],
 ["Bei Abduzensparese weicht das Auge nach innen ab (Esotropie) mit horizontalen Doppelbildern; wegen seines langen intrakraniellen Verlaufs gehört er zu den ersten Hirnnerven, die bei erhöhtem Hirndruck ausfallen."],
 ["Merkhilfe: LR6 SO4, Rest 3 (Rectus lateralis VI, Obliquus superior IV, übrige III)."], ["äußerer gerader Augenmuskel"]],
"es": ["Músculo recto lateral", "Músculo fijado a la cara lateral del globo ocular que gira el ojo hacia fuera; el único músculo inervado por el nervio abducens.",
 ["Anillo tendinoso común (parte lateral, dos cabezas)", "Esclera, unos 7 mm lateral y detrás de la córnea", "Nervio abducens (VI)", "Ramas musculares de la arteria oftálmica, arteria lagrimal",
  "Abducción"], [],
 ["En la parálisis del abducens el ojo se desvía hacia dentro (esotropía) con diplopía horizontal; por su largo trayecto intracraneal es de los primeros pares craneales afectados por la hipertensión intracraneal."],
 ["Regla: RL6 OS4, el resto 3 (recto lateral VI, oblicuo superior IV, los demás III)."], []],
},
"m-obliquus-superior": {
"en": ["Superior oblique", "A muscle whose tendon turns through a pulley (trochlea) at the upper medial corner of the orbit to attach to the posterior superolateral quadrant of the eyeball.",
 ["Body of the sphenoid (superomedial to the common tendinous ring)", "Posterior superolateral quadrant of the sclera, after passing through the trochlea", "Trochlear nerve (IV)", "Muscular branches of the ophthalmic artery",
  "Intorsion; depression (most effective with the eye adducted) and abduction"], [],
 ["In trochlear palsy there is vertical double vision when going downstairs and reading; the patient compensates by tilting the head to the healthy side."],
 ["It is the muscle for looking down and in; nerve IV is the only cranial nerve that emerges from the back of the brainstem and decussates completely."], []],
"fr": ["Muscle oblique supérieur", "Muscle dont le tendon se réfléchit dans une poulie (trochlée) à l'angle supéro-médial de l'orbite pour s'insérer sur le quadrant postéro-supéro-latéral du globe.",
 ["Corps du sphénoïde (au-dessus et en dedans de l'anneau tendineux commun)", "Quadrant postéro-supéro-latéral de la sclère, après passage dans la trochlée", "Nerf trochléaire (IV)", "Rameaux musculaires de l'artère ophtalmique",
  "Intorsion ; abaissement (plus efficace œil en adduction) et abduction"], [],
 ["Dans la paralysie du nerf trochléaire, une diplopie verticale apparaît en descendant les escaliers et en lisant ; le patient compense en inclinant la tête du côté sain."],
 ["C'est le muscle du regard en bas et en dedans ; le IV est le seul nerf crânien qui émerge de la face postérieure du tronc cérébral et qui décusse complètement."], ["grand oblique"]],
"de": ["M. obliquus superior", "Muskel, dessen Sehne über eine Rolle (Trochlea) am oberen inneren Orbitawinkel umgelenkt wird und am hinteren oberen äußeren Quadranten des Augapfels ansetzt.",
 ["Corpus ossis sphenoidalis (oberhalb-medial des Anulus tendineus communis)", "Hinterer oberer äußerer Quadrant der Sklera nach Umlenkung an der Trochlea", "N. trochlearis (IV)", "Muskeläste der A. ophthalmica",
  "Innenrollung; Senkung (am wirksamsten bei adduziertem Auge) und Abduktion"], [],
 ["Bei Trochlearisparese entstehen beim Treppabgehen und Lesen vertikale Doppelbilder; der Patient kompensiert durch Kopfneigung zur gesunden Seite."],
 ["Er ermöglicht den Blick nach unten innen; der IV. Hirnnerv ist der einzige, der dorsal aus dem Hirnstamm austritt und vollständig kreuzt."], ["oberer schräger Augenmuskel"]],
"es": ["Músculo oblicuo superior", "Músculo cuyo tendón se refleja en una polea (tróclea) del ángulo superomedial de la órbita para insertarse en el cuadrante posterosuperolateral del globo ocular.",
 ["Cuerpo del esfenoides (superomedial al anillo tendinoso común)", "Cuadrante posterosuperolateral de la esclera, tras pasar por la tróclea", "Nervio troclear (IV)", "Ramas musculares de la arteria oftálmica",
  "Intorsión; depresión (más eficaz con el ojo en aducción) y abducción"], [],
 ["En la parálisis del troclear hay diplopía vertical al bajar escaleras y leer; el paciente compensa inclinando la cabeza hacia el lado sano."],
 ["Es el músculo de la mirada abajo y adentro; el IV par es el único que sale por la cara posterior del tronco del encéfalo y se decusa por completo."], ["oblicuo mayor"]],
},
"m-obliquus-inferior": {
"en": ["Inferior oblique", "A muscle that arises from the anterior floor of the orbit, passes beneath the eyeball and attaches to its posterolateral quadrant; the only extra-ocular muscle not arising from the tendinous ring.",
 ["Anteromedial floor of the orbit (maxilla, lateral to the fossa for the lacrimal sac)", "Posterior inferolateral quadrant of the sclera", "Oculomotor nerve (III), inferior division",
  "Muscular branches of the ophthalmic artery, infraorbital artery", "Extorsion; elevation (most effective with the eye adducted) and abduction"], [], [],
 ["It produces upward and inward gaze; it is the only extra-ocular muscle arising from the floor of the orbit rather than the orbital apex."], []],
"fr": ["Muscle oblique inférieur", "Muscle né de la partie antérieure du plancher de l'orbite, qui passe sous le globe oculaire pour s'insérer sur son quadrant postéro-latéral ; seul oculomoteur qui ne naît pas de l'anneau tendineux.",
 ["Partie antéro-médiale du plancher de l'orbite (maxillaire, en dehors de la fosse du sac lacrymal)", "Quadrant postéro-inféro-latéral de la sclère", "Nerf oculomoteur (III), branche inférieure",
  "Rameaux musculaires de l'artère ophtalmique, artère infra-orbitaire", "Extorsion ; élévation (plus efficace œil en adduction) et abduction"], [], [],
 ["Il assure le regard en haut et en dedans ; c'est le seul oculomoteur qui naît du plancher de l'orbite et non de l'apex orbitaire."], ["petit oblique"]],
"de": ["M. obliquus inferior", "Muskel, der vom vorderen Orbitaboden entspringt, unter dem Augapfel hindurchzieht und am hinteren äußeren Quadranten ansetzt; der einzige äußere Augenmuskel, der nicht vom Anulus tendineus entspringt.",
 ["Vorderer medialer Orbitaboden (Maxilla, lateral der Fossa sacci lacrimalis)", "Hinterer unterer äußerer Quadrant der Sklera", "N. oculomotorius (III), unterer Ast",
  "Muskeläste der A. ophthalmica, A. infraorbitalis", "Außenrollung; Hebung (am wirksamsten bei adduziertem Auge) und Abduktion"], [], [],
 ["Er ermöglicht den Blick nach oben innen; er ist der einzige äußere Augenmuskel, der vom Orbitaboden und nicht von der Orbitaspitze entspringt."], ["unterer schräger Augenmuskel"]],
"es": ["Músculo oblicuo inferior", "Músculo que nace de la parte anterior del suelo de la órbita, pasa bajo el globo ocular y se inserta en su cuadrante posterolateral; el único extraocular que no nace del anillo tendinoso.",
 ["Parte anteromedial del suelo de la órbita (maxilar, lateral a la fosa del saco lagrimal)", "Cuadrante posteroinferolateral de la esclera", "Nervio oculomotor (III), rama inferior",
  "Ramas musculares de la arteria oftálmica, arteria infraorbitaria", "Extorsión; elevación (más eficaz con el ojo en aducción) y abducción"], [], [],
 ["Produce la mirada hacia arriba y adentro; es el único extraocular que nace del suelo de la órbita y no del vértice orbitario."], ["oblicuo menor"]],
},
"m-levator-palpebrae": {
"en": ["Levator palpebrae superioris", "The muscle that raises the upper eyelid; the smooth muscle fibres on its underside (superior tarsal muscle, Müller's muscle) have a sympathetic supply.",
 ["Lesser wing of the sphenoid (above the optic canal)", "Skin of the upper eyelid and superior tarsus", "Oculomotor nerve (III), superior division; smooth muscle part sympathetic fibres",
  "Muscular branches of the ophthalmic artery", "Raises the upper eyelid"], [],
 ["In oculomotor palsy there is complete ptosis; in Horner syndrome only Müller's muscle is affected, so the ptosis is mild."], [], ["levator", "eyelid"]],
"fr": ["Muscle releveur de la paupière supérieure", "Muscle qui élève la paupière supérieure ; les fibres musculaires lisses de sa face inférieure (muscle tarsal supérieur, muscle de Müller) ont une innervation sympathique.",
 ["Petite aile du sphénoïde (au-dessus du canal optique)", "Peau de la paupière supérieure et tarse supérieur", "Nerf oculomoteur (III), branche supérieure ; partie lisse : fibres sympathiques",
  "Rameaux musculaires de l'artère ophtalmique", "Élève la paupière supérieure"], [],
 ["Dans la paralysie de l'oculomoteur, le ptosis est complet ; dans le syndrome de Claude Bernard-Horner, seul le muscle de Müller est touché, d'où un ptosis discret."], [], ["releveur", "paupière"]],
"de": ["M. levator palpebrae superioris", "Muskel, der das Oberlid hebt; die glatten Muskelfasern an seiner Unterseite (M. tarsalis superior, Müller-Muskel) sind sympathisch innerviert.",
 ["Ala minor ossis sphenoidalis (oberhalb des Canalis opticus)", "Haut des Oberlids und Tarsus superior", "N. oculomotorius (III), oberer Ast; glatter Muskelanteil sympathische Fasern",
  "Muskeläste der A. ophthalmica", "Hebt das Oberlid"], [],
 ["Bei Okulomotoriusparese besteht eine vollständige Ptosis; beim Horner-Syndrom ist nur der Müller-Muskel betroffen, daher ist die Ptosis gering."], [], ["Lidheber", "Augenlid"]],
"es": ["Músculo elevador del párpado superior", "Músculo que eleva el párpado superior; las fibras de músculo liso de su cara inferior (músculo tarsal superior, de Müller) tienen inervación simpática.",
 ["Ala menor del esfenoides (por encima del conducto óptico)", "Piel del párpado superior y tarso superior", "Nervio oculomotor (III), rama superior; porción lisa: fibras simpáticas",
  "Ramas musculares de la arteria oftálmica", "Eleva el párpado superior"], [],
 ["En la parálisis del oculomotor la ptosis es completa; en el síndrome de Horner solo se afecta el músculo de Müller, por lo que la ptosis es leve."], [], ["elevador", "párpado"]],
},
"m-genioglossus": {
"en": ["Genioglossus", "A fan-shaped extrinsic tongue muscle that forms most of the bulk of the tongue; it protrudes the tongue.",
 ["Superior mental spine (inner surface of the mandible)", "Whole length of the dorsum of the tongue and body of the hyoid bone", "Hypoglossal nerve (XII)", "Lingual artery (deep lingual and sublingual arteries)",
  "Protrudes the tongue; acting on both sides it hollows the centre of the tongue"], [],
 ["In a hypoglossal nerve lesion the protruded tongue deviates towards the side of the lesion (the healthy genioglossus pushes it that way).", "Its relaxation under anaesthesia lets the tongue fall back and block the airway; the jaw-thrust manoeuvre opens it."],
 ["The 'life-saving muscle': it stops the tongue falling backwards."], []],
"fr": ["Muscle génioglosse", "Muscle extrinsèque de la langue en éventail qui en forme l'essentiel ; il tire la langue en avant.",
 ["Épine mentonnière supérieure (face interne de la mandibule)", "Toute la longueur du dos de la langue et corps de l'os hyoïde", "Nerf hypoglosse (XII)", "Artère linguale (artères profonde de la langue et sublinguale)",
  "Tire la langue hors de la bouche ; en contraction bilatérale, creuse le centre de la langue"], [],
 ["Dans une lésion du nerf hypoglosse, la langue tirée dévie du côté de la lésion (le génioglosse sain la pousse de ce côté).", "Son relâchement sous anesthésie fait chuter la langue en arrière et obstrue les voies aériennes ; la subluxation de la mâchoire les libère."],
 ["Le « muscle qui sauve la vie » : il empêche la langue de tomber en arrière."], []],
"de": ["M. genioglossus", "Fächerförmiger äußerer Zungenmuskel, der den Großteil der Zungenmasse bildet; er streckt die Zunge heraus.",
 ["Spina mentalis superior (Innenfläche der Mandibula)", "Gesamte Länge des Zungenrückens und Corpus ossis hyoidei", "N. hypoglossus (XII)", "A. lingualis (A. profunda linguae, A. sublingualis)",
  "Streckt die Zunge heraus; beidseitig vertieft er die Zungenmitte"], [],
 ["Bei Hypoglossusläsion weicht die herausgestreckte Zunge zur Läsionsseite ab (der gesunde Genioglossus schiebt sie dorthin).", "Seine Erschlaffung in Narkose lässt die Zunge zurückfallen und die Atemwege verlegen; der Esmarch-Handgriff öffnet sie."],
 ["Der „lebensrettende Muskel“: Er verhindert das Zurückfallen der Zunge."], []],
"es": ["Músculo geniogloso", "Músculo extrínseco de la lengua en abanico que forma la mayor parte de su masa; saca la lengua.",
 ["Espina mentoniana superior (cara interna de la mandíbula)", "Toda la longitud del dorso de la lengua y cuerpo del hioides", "Nervio hipogloso (XII)", "Arteria lingual (arterias profunda de la lengua y sublingual)",
  "Saca la lengua (protrusión); en contracción bilateral ahueca el centro de la lengua"], [],
 ["En la lesión del hipogloso, la lengua protruida se desvía hacia el lado de la lesión (el geniogloso sano la empuja hacia allí).", "Su relajación en la anestesia hace caer la lengua hacia atrás y obstruye la vía aérea; la maniobra de tracción mandibular la abre."],
 ["El «músculo salvavidas»: impide que la lengua caiga hacia atrás."], []],
},
"m-hyoglossus": {
"en": ["Hyoglossus", "A quadrilateral extrinsic tongue muscle running from the hyoid bone to the side of the tongue; an important landmark in the submandibular region.",
 ["Body and greater horn of the hyoid bone", "Side and underside of the tongue", "Hypoglossal nerve (XII)", "Lingual artery", "Depresses and retracts the tongue"], [], [],
 ["The lingual artery passes deep to this muscle, while the hypoglossal nerve, lingual nerve and submandibular duct pass on its surface."], []],
"fr": ["Muscle hyoglosse", "Muscle extrinsèque quadrilatère de la langue, tendu de l'os hyoïde au bord latéral de la langue ; repère important de la région submandibulaire.",
 ["Corps et grande corne de l'os hyoïde", "Bord latéral et face inférieure de la langue", "Nerf hypoglosse (XII)", "Artère linguale", "Abaisse et rétracte la langue"], [], [],
 ["L'artère linguale passe en profondeur de ce muscle, tandis que le nerf hypoglosse, le nerf lingual et le conduit submandibulaire passent à sa surface."], []],
"de": ["M. hyoglossus", "Viereckiger äußerer Zungenmuskel vom Zungenbein zum Zungenrand; ein wichtiger Orientierungspunkt der Submandibularregion.",
 ["Corpus und Cornu majus ossis hyoidei", "Seitenrand und Unterfläche der Zunge", "N. hypoglossus (XII)", "A. lingualis", "Zieht die Zunge nach unten hinten"], [], [],
 ["Die A. lingualis zieht in der Tiefe dieses Muskels, N. hypoglossus, N. lingualis und Ductus submandibularis dagegen auf seiner Oberfläche."], []],
"es": ["Músculo hiogloso", "Músculo extrínseco cuadrilátero de la lengua que va del hioides al borde lateral de la lengua; referencia importante de la región submandibular.",
 ["Cuerpo y asta mayor del hioides", "Borde lateral y cara inferior de la lengua", "Nervio hipogloso (XII)", "Arteria lingual", "Desciende y retrae la lengua"], [], [],
 ["La arteria lingual pasa profunda a este músculo; el hipogloso, el nervio lingual y el conducto submandibular pasan por su superficie."], []],
},
"m-scalenus-anterior": {
"en": ["Scalenus anterior", "A muscle on the side of the neck running from the cervical vertebrae to the 1st rib; an important boundary between artery and vein.",
 ["Anterior tubercles of the transverse processes of C3–C6", "Scalene tubercle of the 1st rib (Lisfranc's tubercle)", "Anterior rami of spinal nerves C4–C6", "Ascending cervical artery, transverse cervical artery",
  "Raises the 1st rib (forced inspiration); flexes the neck forwards and sideways and rotates it to the opposite side"], [],
 ["In thoracic outlet syndrome the subclavian artery and brachial plexus can be compressed between the anterior and middle scalenes (scalene gap)."],
 ["The phrenic nerve descends on its anterior surface; the subclavian vein passes in front of the muscle, the subclavian artery and brachial plexus behind it."], ["scalene"]],
"fr": ["Muscle scalène antérieur", "Muscle de la face latérale du cou, tendu des vertèbres cervicales à la 1re côte ; limite importante entre artère et veine.",
 ["Tubercules antérieurs des processus transverses de C3–C6", "Tubercule du muscle scalène antérieur de la 1re côte (tubercule de Lisfranc)", "Rameaux antérieurs des nerfs spinaux C4–C6", "Artère cervicale ascendante, artère cervicale transverse",
  "Élève la 1re côte (inspiration forcée) ; fléchit le cou en avant et latéralement et le tourne du côté opposé"], [],
 ["Dans le syndrome du défilé thoracique, l'artère subclavière et le plexus brachial peuvent être comprimés entre les scalènes antérieur et moyen (défilé interscalénique)."],
 ["Le nerf phrénique descend sur sa face antérieure ; la veine subclavière passe en avant du muscle, l'artère subclavière et le plexus brachial en arrière."], ["scalène"]],
"de": ["M. scalenus anterior", "Muskel an der Halsseite von den Halswirbeln zur 1. Rippe; eine wichtige Grenze zwischen Arterie und Vene.",
 ["Tubercula anteriora der Querfortsätze C3–C6", "Tuberculum musculi scaleni anterioris der 1. Rippe (Lisfranc-Höcker)", "Rr. anteriores der Spinalnerven C4–C6", "A. cervicalis ascendens, A. transversa colli",
  "Hebt die 1. Rippe (forcierte Einatmung); beugt den Hals nach vorn und zur Seite und dreht ihn zur Gegenseite"], [],
 ["Beim Thoracic-outlet-Syndrom können A. subclavia und Plexus brachialis zwischen vorderem und mittlerem Skalenus (Skalenuslücke) eingeengt werden."],
 ["Der N. phrenicus zieht auf seiner Vorderfläche abwärts; die V. subclavia verläuft vor dem Muskel, A. subclavia und Plexus brachialis dahinter."], ["vorderer Treppenmuskel", "Skalenus"]],
"es": ["Músculo escaleno anterior", "Músculo de la cara lateral del cuello que va de las vértebras cervicales a la 1.ª costilla; límite importante entre arteria y vena.",
 ["Tubérculos anteriores de las apófisis transversas de C3–C6", "Tubérculo del escaleno anterior de la 1.ª costilla (tubérculo de Lisfranc)", "Ramos anteriores de los nervios espinales C4–C6", "Arteria cervical ascendente, arteria cervical transversa",
  "Eleva la 1.ª costilla (inspiración forzada); flexiona el cuello hacia delante y al lado y lo rota al lado opuesto"], [],
 ["En el síndrome del desfiladero torácico la arteria subclavia y el plexo braquial pueden comprimirse entre los escalenos anterior y medio (hiato de los escalenos)."],
 ["El nervio frénico desciende por su cara anterior; la vena subclavia pasa por delante del músculo, y la arteria subclavia y el plexo braquial por detrás."], ["escaleno"]],
},
"m-scalenus-medius": {
"en": ["Scalenus medius", "The largest and longest of the scalenes, running from the cervical vertebrae to the upper surface of the 1st rib.",
 ["Posterior tubercles of the transverse processes of C2–C7", "Upper surface of the 1st rib (behind the groove for the subclavian artery)", "Anterior rami of spinal nerves C3–C8",
  "Ascending cervical artery, transverse cervical artery", "Raises the 1st rib; bends the neck to the same side"], [], [],
 ["The roots of the dorsal scapular nerve and long thoracic nerve pierce this muscle."], ["scalene"]],
"fr": ["Muscle scalène moyen", "Le plus grand et le plus long des scalènes, tendu des vertèbres cervicales à la face supérieure de la 1re côte.",
 ["Tubercules postérieurs des processus transverses de C2–C7", "Face supérieure de la 1re côte (en arrière du sillon de l'artère subclavière)", "Rameaux antérieurs des nerfs spinaux C3–C8",
  "Artère cervicale ascendante, artère cervicale transverse", "Élève la 1re côte ; incline le cou du même côté"], [], [],
 ["Les racines du nerf dorsal de la scapula et du nerf thoracique long traversent ce muscle."], ["scalène"]],
"de": ["M. scalenus medius", "Der größte und längste Skalenusmuskel, von den Halswirbeln zur Oberfläche der 1. Rippe.",
 ["Tubercula posteriora der Querfortsätze C2–C7", "Oberfläche der 1. Rippe (hinter dem Sulcus arteriae subclaviae)", "Rr. anteriores der Spinalnerven C3–C8",
  "A. cervicalis ascendens, A. transversa colli", "Hebt die 1. Rippe; neigt den Hals zur gleichen Seite"], [], [],
 ["Die Wurzeln des N. dorsalis scapulae und des N. thoracicus longus durchbohren diesen Muskel."], ["mittlerer Treppenmuskel", "Skalenus"]],
"es": ["Músculo escaleno medio", "El más grande y largo de los escalenos, que va de las vértebras cervicales a la cara superior de la 1.ª costilla.",
 ["Tubérculos posteriores de las apófisis transversas de C2–C7", "Cara superior de la 1.ª costilla (detrás del surco de la arteria subclavia)", "Ramos anteriores de los nervios espinales C3–C8",
  "Arteria cervical ascendente, arteria cervical transversa", "Eleva la 1.ª costilla; inclina el cuello hacia el mismo lado"], [], [],
 ["Las raíces del nervio dorsal de la escápula y del torácico largo perforan este músculo."], ["escaleno"]],
},
"m-scalenus-posterior": {
"en": ["Scalenus posterior", "The smallest and deepest of the scalenes; the only scalene attached to the 2nd rib.",
 ["Posterior tubercles of the transverse processes of C4–C6", "Outer surface of the 2nd rib", "Anterior rami of spinal nerves C6–C8", "Ascending cervical artery, superficial cervical artery",
  "Raises the 2nd rib; bends the neck to the same side"], [], [], [], ["scalene"]],
"fr": ["Muscle scalène postérieur", "Le plus petit et le plus profond des scalènes ; le seul qui s'insère sur la 2e côte.",
 ["Tubercules postérieurs des processus transverses de C4–C6", "Face externe de la 2e côte", "Rameaux antérieurs des nerfs spinaux C6–C8", "Artère cervicale ascendante, artère cervicale superficielle",
  "Élève la 2e côte ; incline le cou du même côté"], [], [], [], ["scalène"]],
"de": ["M. scalenus posterior", "Der kleinste und tiefste Skalenusmuskel; der einzige, der an der 2. Rippe ansetzt.",
 ["Tubercula posteriora der Querfortsätze C4–C6", "Außenfläche der 2. Rippe", "Rr. anteriores der Spinalnerven C6–C8", "A. cervicalis ascendens, A. cervicalis superficialis",
  "Hebt die 2. Rippe; neigt den Hals zur gleichen Seite"], [], [], [], ["hinterer Treppenmuskel", "Skalenus"]],
"es": ["Músculo escaleno posterior", "El más pequeño y profundo de los escalenos; el único que se inserta en la 2.ª costilla.",
 ["Tubérculos posteriores de las apófisis transversas de C4–C6", "Cara externa de la 2.ª costilla", "Ramos anteriores de los nervios espinales C6–C8", "Arteria cervical ascendente, arteria cervical superficial",
  "Eleva la 2.ª costilla; inclina el cuello hacia el mismo lado"], [], [], [], ["escaleno"]],
},
"m-digastricus": {
"en": ["Digastric", "A muscle of anterior and posterior bellies joined by an intermediate tendon; it raises the hyoid and helps open the mouth. Its two bellies develop from different pharyngeal arches.",
 ["Posterior belly: mastoid notch (temporal bone); anterior belly: digastric fossa (mandible)", "Intermediate tendon, attached by a fibrous loop to the body and greater horn of the hyoid bone",
  "Posterior belly: facial nerve (VII); anterior belly: nerve to mylohyoid (mandibular nerve, V3)", "Anterior belly: submental artery; posterior belly: occipital and posterior auricular arteries",
  "Raises and steadies the hyoid bone; with the hyoid fixed it depresses the mandible (opens the mouth)"], [], [],
 ["The anterior belly comes from the 1st pharyngeal arch (V3), the posterior belly from the 2nd (VII); it bounds the submandibular and submental triangles."], ["digastric"]],
"fr": ["Muscle digastrique", "Muscle formé d'un ventre antérieur et d'un ventre postérieur réunis par un tendon intermédiaire ; il élève l'os hyoïde et aide à ouvrir la bouche. Ses deux ventres dérivent d'arcs pharyngiens différents.",
 ["Ventre postérieur : incisure mastoïdienne (os temporal) ; ventre antérieur : fosse digastrique (mandibule)", "Tendon intermédiaire, fixé par une boucle fibreuse au corps et à la grande corne de l'os hyoïde",
  "Ventre postérieur : nerf facial (VII) ; ventre antérieur : nerf mylo-hyoïdien (nerf mandibulaire, V3)", "Ventre antérieur : artère submentale ; ventre postérieur : artères occipitale et auriculaire postérieure",
  "Élève et stabilise l'os hyoïde ; hyoïde fixé, abaisse la mandibule (ouvre la bouche)"], [], [],
 ["Le ventre antérieur dérive du 1er arc pharyngien (V3), le postérieur du 2e (VII) ; il limite les trigones submandibulaire et submental."], ["digastrique"]],
"de": ["M. digastricus", "Muskel aus vorderem und hinterem Bauch, verbunden durch eine Zwischensehne; er hebt das Zungenbein und unterstützt die Mundöffnung. Seine beiden Bäuche entstammen verschiedenen Schlundbögen.",
 ["Venter posterior: Incisura mastoidea (Os temporale); Venter anterior: Fossa digastrica (Mandibula)", "Zwischensehne, über eine Bindegewebsschlinge an Corpus und Cornu majus ossis hyoidei befestigt",
  "Venter posterior: N. facialis (VII); Venter anterior: N. mylohyoideus (N. mandibularis, V3)", "Venter anterior: A. submentalis; Venter posterior: A. occipitalis, A. auricularis posterior",
  "Hebt und fixiert das Zungenbein; bei fixiertem Zungenbein senkt er den Unterkiefer (Mundöffnung)"], [], [],
 ["Der vordere Bauch stammt aus dem 1. Schlundbogen (V3), der hintere aus dem 2. (VII); er begrenzt das Trigonum submandibulare und submentale."], ["Digastricus", "zweibäuchiger Muskel"]],
"es": ["Músculo digástrico", "Músculo de vientres anterior y posterior unidos por un tendón intermedio; eleva el hioides y ayuda a abrir la boca. Sus dos vientres proceden de arcos faríngeos distintos.",
 ["Vientre posterior: escotadura mastoidea (temporal); vientre anterior: fosa digástrica (mandíbula)", "Tendón intermedio, fijado por un asa fibrosa al cuerpo y el asta mayor del hioides",
  "Vientre posterior: nervio facial (VII); vientre anterior: nervio milohioideo (nervio mandibular, V3)", "Vientre anterior: arteria submentoniana; vientre posterior: arterias occipital y auricular posterior",
  "Eleva y fija el hioides; con el hioides fijo desciende la mandíbula (abre la boca)"], [], [],
 ["El vientre anterior procede del 1.er arco faríngeo (V3) y el posterior del 2.º (VII); limita los triángulos submandibular y submentoniano."], ["digástrico"]],
},
}
